(22,	'Documents to substantiate the rates of compensation of Tenancy land like copies of agreement with landowners/ previous settlement of compensation, minutes of meeting with landowners, Government certified market value etc. for current land or chronologically nearest previous case of possession of land',	'acquisition',	'N0',	'chkfile-upload',	1,	'5',	NULL,	NULL,	NULL,	't',	NULL,	NULL,	'किरायेदारी (Tenancy) भूमि के मुआवजे की दरों को प्रमाणित करने वाले दस्तावेज जैसे भूस्वामियों के साथ समझौते की प्रतियां/मुआवजे का पिछला निपटान, भूस्वामियों के साथ बैठक का कार्यवृत्त, वर्तमान भूमि या भूमि के कब्जे के कालानुक्रमिक रूप से निकटतम पिछले मामले के लिए सरकार द्वारा प्रमाणित बाजार मूल्य आदि।'),
(79,	'Documents to substantiate the rates of compensation of Tenancy land like copies of agreements with landowners/ previous settlement of compensation, minutes of meeting with landowners, Government certified market value etc. for current land or chronologically nearest previous case of possession of land',	'acquisition',	NULL,	'chkfile-upload',	2,	'5',	NULL,	NULL,	NULL,	't',	NULL,	NULL,	'किरायेदारी (Tenancy) भूमि के मुआवजे की दरों को प्रमाणित करने वाले दस्तावेज जैसे भूस्वामियों के साथ समझौते की प्रतियां/मुआवजे का पिछला निपटान, भूस्वामियों के साथ बैठक का कार्यवृत्त, वर्तमान भूमि या भूमि के कब्जे के कालानुक्रमिक रूप से निकटतम पिछले मामले के लिए सरकार द्वारा प्रमाणित बाजार मूल्य आदि।'),
(80,	'Documents to substantiate the rates of compensation of Government land/ Patta Land like the copy of Government certified market value/ demand of District Authority etc.',	'acquisition',	NULL,	'chkfile-upload',	2,	'5',	NULL,	NULL,	NULL,	't',	NULL,	NULL,	'सरकारी भूमि/पट्टा भूमि के मुआवजे की दरों को प्रमाणित करने वाले दस्तावेज जैसे सरकार द्वारा प्रमाणित बाजार मूल्य की प्रति/जिला प्राधिकरण की मांग आदि।'),
